import json, subprocess, sys, random, itertools
sys.setrecursionlimit(1000000)

def run(reqs):
    data = b"\n".join(json.dumps(r).encode() for r in reqs)
    p = subprocess.run([sys.executable,"-I","/app/submission/main.py"],input=data,
                       stdout=subprocess.PIPE,stderr=subprocess.PIPE,timeout=120)
    if p.returncode!=0:
        print("RC",p.returncode,p.stderr.decode()); sys.exit(1)
    return [json.loads(x) for x in p.stdout.splitlines()]

def expected_sums(inputs):
    P=len(inputs); R=len(inputs[0]) if P else 0; D=len(inputs[0][0]) if R else 0
    out=[]
    for q in range(R):
        v=[0]*D
        for r in range(P):
            for i in range(D): v[i]+=inputs[r][q][i]
        out.append(v)
    return out,P,R,D

def is_safe(st,inputs,P,R,D,exp):
    for r in range(P):
        for q,vec in enumerate(st["delivered"][r]):
            if vec!=exp[q]: return False
    for s in st["slots"]:
        q=s["seq"]; acc=[0]*D
        for rr in s["ranks"]:
            for i in range(D): acc[i]+=inputs[rr][q][i]
        if acc!=s["sum"]: return False
    return True

def is_done(st,P,R):
    return all(len(st["delivered"][r])==R for r in range(P))

def brute_terminates(inputs,states,edges,start,fair,P,R,D):
    n=len(states)
    done=[is_done(states[i],P,R) for i in range(n)]
    if done[start]: return True
    # non-done reachable from start through non-done
    succ=[[] for _ in range(n)]
    for e in edges: succ[e[0]].append((e[2],e[1]))
    N=set([start]); dq=[start]
    while dq:
        s=dq.pop()
        for (t,a) in succ[s]:
            if done[t]: continue
            if t not in N: N.add(t); dq.append(t)
    weak=[a for a,m in fair if m=="weak"]
    strong=[a for a,m in fair if m=="strong"]
    # enabled per state (all explicit edges from s)
    ens={a:set() for a in set(weak)|set(strong)}
    for e in edges:
        if e[1] in ens: ens[e[1]].add(e[0])
    # action edges internal check
    def has_int(S,a):
        for e in edges:
            if e[1]==a and e[0] in S and e[2] in S: return True
        return False
    states_list=list(N)
    # enumerate nonempty subsets of N (limit size)
    for mask in range(1,1<<len(states_list)):
        S=set(states_list[i] for i in range(len(states_list)) if mask>>i&1)
        # strongly connected induced (explicit + stutter)? use explicit edges; single ok
        # build adjacency restricted
        # reachability from arbitrary
        st0=next(iter(S))
        # forward and backward reachability
        def reach(adj):
            seen={st0}; st=[st0]
            while st:
                u=st.pop()
                for v in adj[u]:
                    if v in S and v not in seen: seen.add(v); st.append(v)
            return seen
        fadj={u:[e[2] for e in edges if e[0]==u] for u in S}
        radj={u:[e[0] for e in edges if e[2]==u] for u in S}
        if reach(fadj)!=S or reach(radj)!=S: continue
        ok=True
        for a in weak:
            if S<=ens[a]:
                if not has_int(S,a): ok=False;break
        if not ok: continue
        for a in strong:
            if S & ens[a]:
                if not has_int(S,a): ok=False;break
        if not ok: continue
        return False
    return True

def brute_safety(inputs,states,edges,start,P,R,D):
    exp,_,_,_=expected_sums(inputs)
    n=len(states)
    safe=[is_safe(st,inputs,P,R,D,exp) for st in states]
    succ=[[] for _ in range(n)]
    for e in edges: succ[e[0]].append(e[2])
    seen={start}; dq=[start]
    while dq:
        s=dq.pop()
        if not safe[s]: return False
        for t in succ[s]:
            if t not in seen: seen.add(t); dq.append(t)
    return True

