actions_pool=["a","b","c"]
bad=0
tests=0
for trial in range(3000):
    P=random.randint(1,2)
    R=random.randint(1,2)
    D=random.randint(0,2)
    inputs=[[[random.randint(-3,3) for _ in range(D)] for _ in range(R)] for _ in range(P)]
    n=random.randint(1,6)
    exp,_,_,_=expected_sums(inputs)
    states=[]
    for i in range(n):
        delivered=[]
        for r in range(P):
            ln=random.randint(0,R)
            arr=[]
            for q in range(ln):
                if random.random()<0.8:
                    arr.append(list(exp[q]))
                else:
                    arr.append([random.randint(-5,5) for _ in range(D)])
            delivered.append(arr)
        slots=[]
        # maybe add slots
        used=set()
        for _ in range(random.randint(0,min(2,R))):
            seq=random.randint(0,R-1)
            if seq in used: continue
            used.add(seq)
            ranks=sorted(random.sample(range(P),random.randint(0,P)))
            acc=[0]*D
            for rr in ranks:
                for d in range(D): acc[d]+=inputs[rr][seq][d]
            if random.random()<0.8: sm=acc
            else: sm=[random.randint(-5,5) for _ in range(D)]
            slots.append({"seq":seq,"ranks":ranks,"sum":sm})
        states.append({"delivered":delivered,"slots":slots})
    # edges
    edges=[]
    seen=set()
    for _ in range(random.randint(0,10)):
        s=random.randrange(n); t=random.randrange(n); a=random.choice(actions_pool)
        key=(s,a,t)
        if key in seen: continue
        seen.add(key); edges.append([s,a,t])
    start=random.randrange(n)
    fair=[]
    used=set()
    for _ in range(random.randint(0,3)):
        a=random.choice(actions_pool)
        if a in used: continue
        used.add(a)
        fair.append({"action":a,"mode":random.choice(["weak","strong"])})
    req={"op":"audit","inputs":inputs,"states":states,"edges":edges,"start":start,"fairness":fair}
    try:
        resp=run([req])[0]
    except Exception as e:
        print("EXC",e); print(json.dumps(req)); bad+=1; break
    bt=brute_terminates(inputs,states,edges,start,[(f["action"],f["mode"]) for f in fair],P,R,D)
    bs=brute_safety(inputs,states,edges,start,P,R,D)
    tests+=1
    if resp["terminates"]!=bt or resp["safe"]!=bs:
        bad+=1
        print("MISMATCH trial",trial,"resp term",resp["terminates"],"brute",bt,"safe",resp["safe"],"brute",bs)
        print(json.dumps(req))
        if bad>5: break
